verus! {

    /// Given a non-negative integer `n` and a sequence `s` of exactly `n` moves
    /// ('U' for up, 'R' for right), count the number of times the walk
    /// transitions strictly between region A (x > y) and region B (y > x).
    /// The start at (0,0) is on the border x == y, and the first entry into
    /// a region does _not_ count as a transition.  Time on the border
    /// does not itself count transitions, but leaving the border into a region
    /// compares against the last region visited before touching the border.
    ///
    /// If `n == 0`, returns 0.
    proof fn solve(n: i8, s: Vec<char>) -> i8
        requires
            0 <= n,
            s.len() == (n as usize),
            // each move is either 'U' or 'R'
            forall |j: usize| j < s.len() ==> s[j] == 'U' || s[j] == 'R'
        ensures
            0 <= result,
            result <= n
    {
        // Current coordinates
        let mut x: i8 = 0;
        let mut y: i8 = 0;
        // last_region: 0 = border, 1 = region A (x>y), 2 = region B (y>x)
        let mut last_region: i8 = 0;
        // answer accumulator
        let mut ans: i8 = 0;
        // index into s
        let mut i: usize = 0;

        // Iterate over the moves
        while i < s.len()
            invariant 0 <= i && i <= s.len()
            invariant 0 <= x && 0 <= y
            invariant 0 <= ans && ans <= (i as i8)
            invariant last_region >= 0 && last_region <= 2
            decreases s.len() - i
        {
            // apply move
            if s[i] == 'U' {
                y = y + 1;
            } else {
                x = x + 1;
            }

            // determine current region
            let region: i8 = if x > y {
                1
            } else if y > x {
                2
            } else {
                0
            };

            // if we're strictly in a region now, possibly count a transition
            if region != 0 {
                // count only if we had previously been in a different region
                // and not if this is the very first entry (last_region == 0)
                if last_region != 0 && region != last_region {
                    ans = ans + 1;
                }
                last_region = region;
            }

            i = i + 1;
        }

        ans
    }
}